/* ============ SEOUL BEAT — neon noir UI ============ */
@font-face{font-family:'Bebas Neue';src:url('../fonts/bebas.woff2') format('woff2');font-display:swap}
@font-face{font-family:'Rajdhani';src:url('../fonts/rajdhani-500.woff2') format('woff2');font-weight:500;font-display:swap}
@font-face{font-family:'Rajdhani';src:url('../fonts/rajdhani-600.woff2') format('woff2');font-weight:600;font-display:swap}
@font-face{font-family:'Rajdhani';src:url('../fonts/rajdhani-700.woff2') format('woff2');font-weight:700;font-display:swap}

:root{
  --ink:#07050f;
  --navy:#0d1538;
  --panel:rgba(10,12,30,.62);
  --pink:#ff4d9d;
  --pink-soft:#ff8cc0;
  --cyan:#4fe6ff;
  --gold:#ffd36e;
  --white:#f7f3ff;
  --muted:#9aa4c8;
  --line:rgba(151,180,255,.18);
  --display:'Bebas Neue', 'Arial Narrow', sans-serif;
  --ui:'Rajdhani', 'Segoe UI', sans-serif;
}

*{box-sizing:border-box; -webkit-tap-highlight-color:transparent}
html,body{height:100%; margin:0}
body{
  background:var(--ink);
  color:var(--white);
  font-family:var(--ui);
  overflow:hidden;
  overscroll-behavior:none;
  -webkit-user-select:none; user-select:none;
  touch-action:none;
}
#app{position:fixed; inset:0; overflow:hidden}
#scene{position:absolute; inset:0; width:100%; height:100%; display:block}
.hidden{display:none !important}

/* atmosphere overlays */
.vignette{position:absolute; inset:0; pointer-events:none; z-index:2;
  background:radial-gradient(120% 90% at 50% 42%, transparent 48%, rgba(3,1,10,.72) 100%);
}
.scanlines{position:absolute; inset:0; pointer-events:none; z-index:3; opacity:.16;
  background:repeating-linear-gradient(0deg, rgba(255,255,255,.05) 0 1px, transparent 1px 3px);
  mix-blend-mode:overlay;
}

/* ================= HUD ================= */
.hud{
  position:absolute; z-index:10; top:0; left:0; right:0;
  display:flex; align-items:flex-start; justify-content:space-between; gap:12px;
  padding:calc(14px + env(safe-area-inset-top)) clamp(14px,2vw,28px) 10px;
  pointer-events:none;
  animation:hudIn .5s ease both;
}
@keyframes hudIn{from{opacity:0; transform:translateY(-10px)}to{opacity:1; transform:none}}
.hud-left{display:flex; align-items:center; gap:clamp(12px,2.2vw,30px); min-width:0}
.brand{display:flex; align-items:center; gap:10px}
.brand-mark{
  width:40px; height:40px; display:grid; place-items:center;
  font-family:var(--display); font-size:24px; letter-spacing:1px; color:#0a0a18;
  background:linear-gradient(145deg, var(--cyan), #7da4ff);
  clip-path:polygon(16% 0,100% 0,84% 100%,0 100%);
  box-shadow:0 0 26px rgba(79,230,255,.45);
  padding-bottom:2px;
}
.brand-text{font-family:var(--display); font-size:22px; letter-spacing:2px; line-height:.9; display:flex; flex-direction:column; text-shadow:0 0 16px rgba(255,77,157,.45)}
.brand-text small{font-family:var(--ui); font-weight:600; font-size:8.5px; letter-spacing:3.4px; color:var(--pink-soft); margin-top:4px}
.stat{display:flex; flex-direction:column; line-height:1}
.stat-label{font-size:9.5px; letter-spacing:3px; font-weight:700; color:var(--muted)}
.stat-value{font-family:var(--display); font-size:clamp(26px,3.2vw,40px); letter-spacing:2px; color:var(--gold); text-shadow:0 0 18px rgba(255,211,110,.4); font-variant-numeric:tabular-nums}

.hud-center{display:flex; flex-direction:column; align-items:center; gap:5px; margin-top:2px; width:min(30vw,330px)}
.timer-label{display:flex; align-items:baseline; gap:8px; font-weight:700; letter-spacing:3px; font-size:10px; color:var(--muted)}
.timer-label #timerValue{font-family:var(--display); letter-spacing:1.5px; font-size:26px; color:var(--white); line-height:1; text-shadow:0 0 15px rgba(79,230,255,.45)}
.timer-label small{font-size:9px; letter-spacing:1px; color:var(--cyan); font-weight:700}
.timer-track{position:relative; width:100%; height:7px; background:rgba(120,150,255,.14); border:1px solid var(--line); transform:skewX(-18deg); overflow:hidden}
.timer-fill{position:absolute; inset:0 auto 0 0; width:100%; background:linear-gradient(90deg,var(--cyan),#8aa8ff 55%,var(--pink)); box-shadow:0 0 16px rgba(79,230,255,.6); transition:width .1s linear}
.timer-glow{position:absolute; inset:0; background:linear-gradient(90deg,transparent 70%,rgba(255,255,255,.7) 100%); animation:trackShimmer 2.6s linear infinite; opacity:.5}
@keyframes trackShimmer{from{transform:translateX(-100%)}to{transform:translateX(100%)}}
.timer-track.low .timer-fill{background:linear-gradient(90deg,#ff7a5c,var(--pink)); animation:lowPulse .65s ease infinite alternate}
@keyframes lowPulse{to{filter:brightness(1.5)}}
.combo{opacity:0; transform:translateY(-4px) scale(.85); transition:.2s ease; font-weight:700; font-size:11px; letter-spacing:2px; color:var(--gold); text-shadow:0 0 14px rgba(255,211,110,.6); display:flex; align-items:center; gap:6px}
.combo i{display:block; width:5px; height:5px; background:var(--gold); transform:rotate(45deg); box-shadow:0 0 8px var(--gold)}
.combo.show{opacity:1; transform:none}

.hud-right{display:flex; align-items:center; gap:12px}
.hearts{display:flex; gap:5px; margin-right:2px}
.heart{font-size:clamp(20px,2.4vw,27px); line-height:1; color:var(--pink); filter:drop-shadow(0 0 9px rgba(255,77,157,.65)); transition:.25s ease}
.heart.off{color:#3b3552; filter:none; transform:scale(.86)}
.heart.lost{animation:heartLoss .55s ease}
@keyframes heartLoss{0%{transform:scale(1.5); color:#fff}40%{transform:scale(.7)}100%{transform:scale(.86)}}
.icon-btn{pointer-events:auto; width:34px; height:34px; border:1px solid var(--line); background:rgba(12,16,38,.55); color:var(--muted); display:grid; place-items:center; cursor:pointer; backdrop-filter:blur(8px); transition:.2s; clip-path:polygon(18% 0,100% 0,100% 82%,82% 100%,0 100%,0 18%)}
.icon-btn svg{width:17px; height:17px; fill:currentColor}
.icon-btn:hover{color:var(--white); border-color:rgba(79,230,255,.45); box-shadow:0 0 18px rgba(79,230,255,.18)}
.ico-off{display:none}
.muted .ico-on{display:none}
.muted .ico-off{display:block}

/* minimap */
.minimap-wrap{position:absolute; z-index:9; left:calc(16px + env(safe-area-inset-left)); bottom:calc(16px + env(safe-area-inset-bottom)); width:170px; padding:8px 8px 6px;
  background:linear-gradient(160deg,rgba(10,15,36,.78),rgba(8,6,20,.62)); border:1px solid rgba(120,160,255,.22);
  backdrop-filter:blur(10px); clip-path:polygon(0 0,100% 0,100% calc(100% - 12px),calc(100% - 12px) 100%,0 100%); pointer-events:none;
  box-shadow:0 14px 40px rgba(0,0,0,.45); animation:hudIn .5s .1s ease both}
.map-head{display:flex; align-items:center; gap:5px; font-size:8.5px; letter-spacing:1.8px; font-weight:700; color:#b9c6ec; margin-bottom:5px}
.map-head .dot{width:5px; height:5px; background:var(--cyan); border-radius:50%; box-shadow:0 0 8px var(--cyan); animation:blink 1.6s infinite}
.map-head small{margin-left:auto; color:var(--pink); font-size:7px; letter-spacing:1px}
#minimap{display:block; width:100%; height:auto; background:rgba(4,6,18,.7); border:1px solid rgba(120,160,255,.12)}
.map-legend{display:flex; align-items:center; gap:4px; font-size:7px; letter-spacing:.8px; color:#8b98be; margin-top:5px}
.map-legend span.lg{width:5px; height:5px; display:inline-block; margin-left:5px}
.map-legend .you{background:var(--cyan); box-shadow:0 0 5px var(--cyan)}
.map-legend .thief{background:var(--pink); box-shadow:0 0 5px var(--pink)}
.map-legend .loot{background:var(--gold); box-shadow:0 0 5px var(--gold)}

/* controls hints */
.hints{position:absolute; z-index:9; bottom:calc(20px + env(safe-area-inset-bottom)); left:50%; transform:translateX(-50%);
  display:flex; gap:16px; align-items:center; padding:8px 16px; background:rgba(8,11,26,.55);
  border:1px solid rgba(140,170,255,.14); border-radius:2px; backdrop-filter:blur(8px); pointer-events:none;
  font-size:9px; font-weight:700; letter-spacing:1.4px; color:#8f9cc4; white-space:nowrap}
.hints span{display:flex; align-items:center; gap:5px}
kbd{font-family:var(--ui); font-weight:700; font-size:8.5px; letter-spacing:.5px; color:#dfe6ff; background:rgba(255,255,255,.08); border:1px solid rgba(170,190,255,.25); border-bottom-width:2px; padding:2px 5px; min-width:18px; text-align:center; border-radius:2px}

/* dash button */
.dash-btn{position:absolute; z-index:12; right:calc(22px + env(safe-area-inset-right)); bottom:calc(24px + env(safe-area-inset-bottom));
  width:104px; height:104px; border-radius:50%; border:0; background:transparent; cursor:pointer; pointer-events:auto; padding:0; touch-action:none}
.dash-ring{position:absolute; inset:0; border-radius:50%;
  background:conic-gradient(from -90deg, var(--pink) calc(var(--cd,1) * 360deg), rgba(255,255,255,.08) 0);
  -webkit-mask:radial-gradient(circle, transparent 62%, #000 64%); mask:radial-gradient(circle, transparent 62%, #000 64%);
  filter:drop-shadow(0 0 10px rgba(255,77,157,.5)); transition:background .08s linear}
.dash-inner{position:absolute; inset:12px; border-radius:50%; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:1px;
  background:radial-gradient(circle at 38% 30%, #2a1745, #100c22 75%); border:1px solid rgba(255,120,180,.4);
  box-shadow:inset 0 0 24px rgba(255,77,157,.28), 0 0 30px rgba(255,77,157,.18); color:#ffd9e9; transition:transform .1s ease, filter .2s}
.dash-inner b{font-family:var(--display); font-size:22px; letter-spacing:2px; line-height:1; padding-top:2px}
.dash-inner small{font-size:7px; letter-spacing:2px; color:#ff9fc4; font-weight:700}
.dash-btn:active .dash-inner{transform:scale(.94)}
.dash-btn.cooling .dash-inner{filter:saturate(.25) brightness(.7)}
.dash-btn.ready .dash-inner{animation:readyPulse 2.2s ease infinite}
@keyframes readyPulse{0%,100%{box-shadow:inset 0 0 24px rgba(255,77,157,.28),0 0 22px rgba(255,77,157,.14)}50%{box-shadow:inset 0 0 30px rgba(255,77,157,.45),0 0 40px rgba(255,77,157,.35)}}

/* joystick */
.stick{position:absolute; z-index:11; left:0; top:0; width:clamp(118px,22vw,148px); height:clamp(118px,22vw,148px); pointer-events:none; transform:translate(-50%,-50%); opacity:0; transition:opacity .15s}
.stick.on{opacity:1}
.stick-base{position:absolute; inset:0; border-radius:50%; border:1px solid rgba(120,200,255,.32); background:radial-gradient(circle,rgba(20,30,66,.55),rgba(8,10,24,.15) 70%); box-shadow:0 0 30px rgba(30,80,160,.18), inset 0 0 24px rgba(80,180,255,.08)}
.stick-base:before{content:''; position:absolute; inset:14px; border-radius:50%; border:1px dashed rgba(120,200,255,.13)}
.stick-knob{position:absolute; width:48px; height:48px; left:50%; top:50%; transform:translate(-50%,-50%); border-radius:50%;
  background:radial-gradient(circle at 35% 30%, rgba(255,255,255,.32), rgba(79,230,255,.22) 40%, rgba(20,30,60,.8));
  border:1px solid rgba(160,235,255,.5); box-shadow:0 0 18px rgba(79,230,255,.35)}
.stick-label{position:absolute; bottom:-16px; left:50%; transform:translateX(-50%); font-size:7px; letter-spacing:2.5px; color:rgba(190,215,255,.55); font-weight:700; white-space:nowrap}

/* banner + toasts */
.banner{position:absolute; z-index:14; top:26%; left:50%; transform:translate(-50%,0); pointer-events:none; text-align:center;
  font-family:var(--display); font-size:clamp(38px,6vw,74px); letter-spacing:5px; color:#fff; opacity:0;
  text-shadow:0 0 30px rgba(79,230,255,.65), 0 0 70px rgba(255,77,157,.35); white-space:nowrap}
.banner.show{animation:bannerPop 1.25s cubic-bezier(.2,.9,.25,1) both}
.banner.pink{color:#ffe3f1; text-shadow:0 0 30px rgba(255,77,157,.7),0 0 70px rgba(255,77,157,.35)}
@keyframes bannerPop{0%{opacity:0; transform:translate(-50%,14px) scale(.85)}12%{opacity:1; transform:translate(-50%,0) scale(1.04)}22%{transform:translate(-50%,0) scale(1)}78%{opacity:1}100%{opacity:0; transform:translate(-50%,-14px) scale(1)}}

.toasts{position:absolute; z-index:13; left:50%; bottom:30%; transform:translateX(-50%); display:flex; flex-direction:column-reverse; align-items:center; gap:6px; pointer-events:none}
.toast{font-weight:700; letter-spacing:1.5px; font-size:clamp(13px,1.7vw,17px); color:var(--gold); text-shadow:0 0 14px rgba(255,211,110,.55); animation:toastUp 1.25s ease-out both; white-space:nowrap}
.toast.cyan{color:var(--cyan); text-shadow:0 0 14px rgba(79,230,255,.6)}
.toast.pink{color:var(--pink-soft); text-shadow:0 0 14px rgba(255,77,157,.6)}
.toast small{font-size:.72em; letter-spacing:2px; opacity:.8}
@keyframes toastUp{0%{opacity:0; transform:translateY(12px) scale(.9)}15%{opacity:1; transform:translateY(0) scale(1)}70%{opacity:1}100%{opacity:0; transform:translateY(-22px)}}

/* ================= OVERLAYS ================= */
.overlay{position:absolute; inset:0; z-index:20}
.menu{background:linear-gradient(90deg, rgba(4,3,12,.96) 0%, rgba(5,4,14,.86) 34%, rgba(5,4,14,.25) 62%, rgba(4,3,12,.55) 100%); display:flex; align-items:center}
.menu-shade{position:absolute; inset:0; background:linear-gradient(0deg, rgba(5,3,14,.85), transparent 45%); pointer-events:none}
.menu-card{position:relative; width:min(560px, 50vw); margin-left:clamp(26px,6vw,90px); padding:20px 0; z-index:1; animation:cardIn .8s cubic-bezier(.2,.8,.2,1) both}
@keyframes cardIn{from{opacity:0; transform:translateX(-26px)}to{opacity:1; transform:none}}
.menu-eyebrow{display:flex; align-items:center; gap:8px; font-size:10px; letter-spacing:2.6px; font-weight:700; color:#aebbe0; margin-bottom:14px}
.live-dot{width:7px; height:7px; border-radius:50%; background:var(--pink); box-shadow:0 0 12px var(--pink); animation:blink 1.4s infinite}
@keyframes blink{0%,100%{opacity:1}50%{opacity:.25}}
.title{margin:0; font-family:var(--display); font-weight:400; line-height:.78; letter-spacing:5px; display:flex; flex-direction:column; filter:drop-shadow(0 0 28px rgba(255,77,157,.18))}
.title-top{font-size:clamp(68px,10.5vw,128px); color:var(--white); text-shadow:0 0 1px #fff, 0 0 22px rgba(79,230,255,.55), 0 0 60px rgba(79,230,255,.28)}
.title-bottom{font-size:clamp(84px,12.5vw,158px); color:transparent; -webkit-text-stroke:2px var(--pink); text-shadow:0 0 24px rgba(255,77,157,.6), 0 0 70px rgba(255,77,157,.35); letter-spacing:10px; margin-left:2px}
.title-kr{font-size:13px; letter-spacing:9px; color:var(--pink-soft); margin:8px 0 20px; font-weight:600; opacity:.85}
.menu-lead{max-width:430px; font-size:15px; line-height:1.5; color:#c3cbe4; margin:0 0 16px; font-weight:500}
.menu-lead b{color:var(--white); font-weight:700}
.menu-rules{list-style:none; margin:0 0 22px; padding:0; display:flex; flex-direction:column; gap:7px}
.menu-rules li{position:relative; padding-left:17px; font-size:12.5px; letter-spacing:.3px; color:#98a4c6; font-weight:500}
.menu-rules li:before{content:'◆'; position:absolute; left:0; top:1px; font-size:8px; color:var(--cyan); opacity:.85}
.menu-rules b{color:#eef1ff; font-weight:700}

.start-btn{position:relative; display:inline-flex; align-items:center; gap:14px; border:0; cursor:pointer; pointer-events:auto;
  padding:15px 26px 14px; background:linear-gradient(100deg,var(--pink),#ff6f9f 55%,#ffb1cf); color:#1a0714;
  font-family:var(--display); font-size:23px; letter-spacing:2.5px; clip-path:polygon(0 0,100% 0,100% calc(100% - 12px),calc(100% - 12px) 100%,0 100%);
  box-shadow:0 0 34px rgba(255,77,157,.35), inset 0 0 0 1px rgba(255,255,255,.35); transition:.2s; overflow:hidden}
.start-btn svg{width:20px; height:20px; fill:#1a0714}
.start-btn:before{content:''; position:absolute; inset:0; background:linear-gradient(100deg,transparent 20%,rgba(255,255,255,.5) 48%,transparent 70%); transform:translateX(-120%); transition:transform .55s ease}
.start-btn:hover{transform:translateY(-2px); box-shadow:0 8px 44px rgba(255,77,157,.5)}
.start-btn:hover:before{transform:translateX(120%)}
.start-btn:active{transform:translateY(0) scale(.985)}
.start-btn.small{font-size:19px; padding:12px 22px 11px; margin:6px auto 10px; display:flex; width:fit-content}
.menu-foot{display:flex; align-items:center; gap:22px; margin-top:18px}
.best{font-size:9px; letter-spacing:2.4px; font-weight:700; color:#7f8aad}
.best b{font-family:var(--display); font-size:19px; letter-spacing:1px; color:var(--gold); margin-left:5px; vertical-align:-2px}
.sound-toggle{border:1px solid rgba(150,175,255,.22); background:transparent; color:#8f9bc0; font-family:var(--ui); font-weight:700; font-size:8.5px; letter-spacing:1.6px; padding:6px 10px; cursor:pointer; pointer-events:auto; transition:.2s}
.sound-toggle:hover{color:#fff; border-color:rgba(160,235,255,.45)}
.officer-tag{position:absolute; right:clamp(26px,5vw,70px); bottom:clamp(96px,15vh,150px); display:flex; align-items:flex-start; gap:12px; z-index:1; text-align:right; pointer-events:none; animation:cardIn .9s .2s ease both}
.tag-line{width:34px; height:1px; background:linear-gradient(90deg,transparent,var(--cyan)); margin-top:9px}
.officer-tag small{display:block; font-size:7.5px; letter-spacing:3px; color:var(--cyan); font-weight:700}
.officer-tag strong{display:block; font-family:var(--display); font-size:22px; letter-spacing:2px; color:#fff; margin:1px 0 2px}
.officer-tag em{font-style:normal; font-size:7px; letter-spacing:1.6px; color:#8792b4; font-weight:600}
.menu-controls{position:absolute; left:clamp(26px,6vw,90px); bottom:calc(22px + env(safe-area-inset-bottom)); display:flex; gap:15px; align-items:center; font-size:8.5px; font-weight:600; letter-spacing:1.2px; color:#7d88a9; flex-wrap:wrap; max-width:60vw}
.mc-title{color:var(--pink-soft); font-weight:700; letter-spacing:2px}
.menu-controls kbd{font-size:8px}
.touch-only{display:none}

/* modals */
.modal{display:grid; place-items:center; background:rgba(4,3,12,.78); backdrop-filter:blur(12px); z-index:30}
.modal-card{position:relative; width:min(440px, 90vw); text-align:center; padding:34px 34px 28px; background:linear-gradient(165deg, rgba(20,22,50,.9), rgba(8,7,20,.95));
  border:1px solid rgba(140,170,255,.22); clip-path:polygon(0 0,100% 0,100% calc(100% - 20px),calc(100% - 20px) 100%,0 100%);
  box-shadow:0 30px 90px rgba(0,0,0,.6), inset 0 0 60px rgba(79,230,255,.04); animation:modalIn .35s ease both}
@keyframes modalIn{from{opacity:0; transform:translateY(16px) scale(.97)}to{opacity:1; transform:none}}
.modal-card:before{content:''; position:absolute; top:0; left:0; right:0; height:2px; background:linear-gradient(90deg,transparent,var(--pink),var(--cyan),transparent)}
.modal-kicker{font-size:9px; letter-spacing:3px; font-weight:700; color:var(--cyan); margin-bottom:6px}
.modal-card h2{font-family:var(--display); font-size:52px; font-weight:400; letter-spacing:4px; margin:0 0 6px; color:#fff; text-shadow:0 0 30px rgba(79,230,255,.35)}
.modal-card p{color:#9aa5c8; font-size:12.5px; margin:0 0 18px; letter-spacing:.4px}
.ghost-btn{display:block; margin:4px auto 0; background:transparent; border:1px solid rgba(150,175,255,.2); color:#97a3c8; font-family:var(--ui); font-weight:700; font-size:9px; letter-spacing:2px; padding:9px 20px; cursor:pointer; pointer-events:auto; transition:.2s}
.ghost-btn:hover{color:#fff; border-color:rgba(255,77,157,.5)}
.gameover-card{width:min(480px,92vw)}
.result-score{display:flex; flex-direction:column; gap:2px; margin:10px 0 16px}
.result-score small{font-size:9px; letter-spacing:3px; color:#8e9abe; font-weight:700}
.result-score b{font-family:var(--display); font-size:clamp(58px,9vw,84px); line-height:.95; letter-spacing:3px; color:var(--gold); text-shadow:0 0 26px rgba(255,211,110,.4); font-variant-numeric:tabular-nums}
.result-grid{display:grid; grid-template-columns:repeat(3,1fr); gap:6px; margin-bottom:14px}
.result-grid>div{padding:9px 4px; background:rgba(255,255,255,.03); border:1px solid rgba(140,170,255,.1); display:flex; flex-direction:column; gap:2px}
.result-grid small{font-size:7.5px; letter-spacing:1.6px; color:#838eb1; font-weight:700}
.result-grid b{font-family:var(--display); font-size:24px; letter-spacing:1px; color:#e9edff}
.go-rank{font-size:11px; letter-spacing:1.2px; color:var(--pink-soft); min-height:16px; margin-bottom:6px}
#againBtn{margin-bottom:2px}

/* loading */
.loading{display:flex; flex-direction:column; align-items:center; justify-content:center; gap:14px; background:radial-gradient(circle at 50% 45%, #16102e, #05040c 70%); z-index:50; transition:opacity .6s ease}
.loading.done{opacity:0; pointer-events:none}
.loader-badge{width:64px; height:64px; display:grid; place-items:center; font-family:var(--display); font-size:36px; color:#0a0a18; background:linear-gradient(145deg,var(--cyan),#7da4ff); clip-path:polygon(16% 0,100% 0,84% 100%,0 100%); box-shadow:0 0 44px rgba(79,230,255,.4); animation:loaderPulse 1.4s ease infinite}
@keyframes loaderPulse{50%{filter:brightness(1.25)}}
.loader-text{font-size:9px; letter-spacing:3px; font-weight:700; color:#95a2c9}
.loader-text span{animation:blink 1s infinite}
.loader-bar{width:180px; height:2px; background:rgba(140,170,255,.16); overflow:hidden}
.loader-bar i{display:block; width:40%; height:100%; background:linear-gradient(90deg,transparent,var(--pink),transparent); animation:loadSlide 1.1s ease infinite}
@keyframes loadSlide{from{transform:translateX(-100%)}to{transform:translateX(300%)}}
.rotate-hint{display:none}

/* ================= RESPONSIVE ================= */
@media (pointer:coarse){
  .touch-only{display:inline}
  .hints{display:none !important}
}
@media (max-width:900px){
  .brand-text{display:none}
  .brand-mark{width:34px; height:34px; font-size:21px}
  .hud-center{width:min(34vw,260px)}
  .minimap-wrap{width:132px; left:12px; bottom:calc(12px + env(safe-area-inset-bottom))}
  .hints{display:none !important}
  .menu-card{width:min(560px, 58vw); margin-left:26px}
  .officer-tag{right:24px; bottom:120px}
  .menu-controls{max-width:55vw; gap:10px}
}
@media (max-width:680px){
  .hud{padding:calc(9px + env(safe-area-inset-top)) 12px 8px; gap:6px}
  .hud-left{gap:10px}
  .brand{display:none}
  .stat-label{font-size:8px; letter-spacing:2px}
  .stat-value{font-size:27px}
  .hud-center{width:38vw; margin-top:0}
  .timer-label #timerValue{font-size:21px}
  .timer-label{font-size:8px; gap:5px; letter-spacing:2px}
  .timer-track{height:5px}
  .hearts{gap:1px}
  .heart{font-size:19px}
  .icon-btn{width:29px; height:29px}
  .hud-right{gap:5px}
  .minimap-wrap{width:112px; padding:6px; bottom:calc(100px + env(safe-area-inset-bottom)); top:auto}
  .map-head{font-size:7px; letter-spacing:1px}
  .map-legend{display:none}
  .dash-btn{width:84px; height:84px; right:14px; bottom:calc(18px + env(safe-area-inset-bottom))}
  .dash-inner{inset:9px}
  .dash-inner b{font-size:18px}
  .dash-inner small{font-size:6px}
  .menu{background:linear-gradient(0deg, rgba(4,3,12,.97) 0%, rgba(5,4,14,.9) 48%, rgba(5,4,14,.18) 100%); align-items:flex-end}
  .menu-card{width:auto; margin:0 18px calc(84px + env(safe-area-inset-bottom)); padding:0 0 8px}
  .menu-eyebrow{font-size:8px; letter-spacing:1.8px; margin-bottom:8px}
  .title-top{font-size:clamp(56px,17vw,86px); letter-spacing:3px}
  .title-bottom{font-size:clamp(70px,21vw,104px); letter-spacing:6px}
  .title-kr{font-size:9px; letter-spacing:6px; margin:4px 0 10px}
  .menu-lead{font-size:12px; margin-bottom:8px; max-width:92%}
  .menu-rules{display:none}
  .start-btn{font-size:20px; padding:13px 22px 12px; width:100%; justify-content:center}
  .menu-foot{margin-top:10px; justify-content:space-between}
  .sound-toggle{font-size:8px}
  .officer-tag{display:none}
  .menu-controls{display:none}
  .combo{font-size:9px}
  .banner{top:22%; font-size:44px}
  .toasts{bottom:34%}
}
@media (max-height:520px) and (orientation:landscape){
  .menu-card{margin-left:22px; padding:4px 0}
  .menu-eyebrow{margin-bottom:4px; font-size:8px}
  .title-top{font-size:54px}
  .title-bottom{font-size:66px}
  .title-kr{margin:2px 0 8px; font-size:9px}
  .menu-lead{font-size:11px; margin-bottom:8px}
  .menu-rules{display:none}
  .start-btn{font-size:18px; padding:10px 20px 9px}
  .menu-foot{margin-top:8px}
  .menu-controls{bottom:12px; font-size:7px}
  .officer-tag{bottom:50px}
  .officer-tag strong{font-size:17px}
  .hints{display:none !important}
  .minimap-wrap{width:104px}
  .dash-btn{width:82px; height:82px}
  .hud{padding-top:8px}
}
@media (min-width:1200px){
  .minimap-wrap{width:190px}
  .hints{bottom:26px}
}

