import * as THREE from '../vendor/three.module.js';

// Seoul Beat: compact, self-contained 3D patrol game.
const $ = id => document.getElementById(id);
const canvas = $('scene');
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x09091a);
scene.fog = new THREE.FogExp2(0x09091a, 0.027);
const camera = new THREE.PerspectiveCamera(42, innerWidth / innerHeight, .1, 180);
const renderer = new THREE.WebGLRenderer({canvas, antialias:true, alpha:false, powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.8));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.12;

scene.add(new THREE.HemisphereLight(0x9caaff, 0x191023, 1.7));
const moon = new THREE.DirectionalLight(0x9bb7ff, 2.15);
moon.position.set(-8,18,8); moon.castShadow = true;
moon.shadow.mapSize.set(1024,1024); moon.shadow.camera.left=-25; moon.shadow.camera.right=25;
moon.shadow.camera.top=25; moon.shadow.camera.bottom=-25; moon.shadow.bias=-.001;
scene.add(moon);
const pinkLight = new THREE.PointLight(0xff368c, 28, 24, 2); pinkLight.position.set(-8,5,-4); scene.add(pinkLight);
const cyanLight = new THREE.PointLight(0x31cfff, 25, 26, 2); cyanLight.position.set(8,4,6); scene.add(cyanLight);
const warmLight = new THREE.PointLight(0xffb86a, 12, 14, 2); warmLight.position.set(0,4,-10); scene.add(warmLight);

const mat = (color, roughness=.76, metalness=.04, extra={}) => new THREE.MeshStandardMaterial({color,roughness,metalness,...extra});
const mats = {
  asphalt:mat(0x171929,.92), sidewalk:mat(0x25283b,.93), curb:mat(0x53566b,.85),
  navy:mat(0x182b50,.46,.12), navyDark:mat(0x101a34,.5,.1), shirt:mat(0xdce6f6,.53),
  skin:mat(0xe9b99b,.72), hair:mat(0x21172a,.37), black:mat(0x11131b,.38,.08), gold:mat(0xe9bd64,.32,.55),
  pink:mat(0xff438c,.42,.13,{emissive:0x9b1748,emissiveIntensity:.65}),
  cyan:mat(0x57e6ff,.38,.1,{emissive:0x08738d,emissiveIntensity:.6}),
  thief:mat(0x321f40,.63), red:mat(0xf25871,.6), concrete:mat(0x20243a,.89), glass:mat(0x121a35,.25,.35,{emissive:0x101e3c,emissiveIntensity:.35})
};
const boxGeo = new THREE.BoxGeometry(1,1,1);
const cylGeo = new THREE.CylinderGeometry(1,1,1,12);
const sphereGeo = new THREE.SphereGeometry(1,16,12);
const ground = new THREE.Mesh(new THREE.PlaneGeometry(200,200), mats.asphalt);
ground.rotation.x=-Math.PI/2; ground.position.y=-.09; ground.receiveShadow=true; scene.add(ground);

// Texture-painted neon signs keep every visual self-contained/offline.
function signTexture(text, color='#ff72b1', sub='SEOUL • 서울'){
  const c=document.createElement('canvas'); c.width=512;c.height=160;
  const x=c.getContext('2d'); x.clearRect(0,0,512,160);
  x.fillStyle='rgba(8,9,24,.92)'; x.fillRect(4,8,504,144);
  x.strokeStyle=color; x.lineWidth=5; x.strokeRect(7,11,498,138);
  x.shadowColor=color; x.shadowBlur=22; x.fillStyle=color; x.textAlign='center';
  x.font='bold 54px sans-serif'; x.fillText(text,256,80);
  x.shadowBlur=8; x.font='bold 20px sans-serif'; x.fillStyle='#b8c5e8'; x.fillText(sub,256,119);
  const t=new THREE.CanvasTexture(c); t.colorSpace=THREE.SRGBColorSpace; return t;
}
function addBox(parent, material, pos, scale, cast=true){
  const m=new THREE.Mesh(boxGeo,material); m.position.set(...pos); m.scale.set(...scale); m.castShadow=cast; m.receiveShadow=true; parent.add(m); return m;
}
function addCylinder(parent, material, pos, r1, r2, h, seg=12){
  const m=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,seg),material);m.position.set(...pos);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;
}
function addSphere(parent, material, pos, scale){
  const m=new THREE.Mesh(sphereGeo,material);m.position.set(...pos);m.scale.set(...scale);m.castShadow=true;parent.add(m);return m;
}
function neonSign(parent,text,color,pos,scale=[2.6,.82,.08]){
  const tex=signTexture(text,color);const material=new THREE.MeshBasicMaterial({map:tex,transparent:true,side:THREE.DoubleSide});
  const mesh=new THREE.Mesh(new THREE.PlaneGeometry(scale[0],scale[1]),material);mesh.position.set(...pos);parent.add(mesh);
}

// Neighborhood perimeter: buildings, glowing windows, alleys and Korean shop fronts.
const city = new THREE.Group(); scene.add(city);
function building(x,z,w,d,h,sign,color){
  const g=new THREE.Group();g.position.set(x,0,z);city.add(g);
  addBox(g,mat(0x171b30,.9),[0,h/2,0],[w,h,d]);
  addBox(g,mat(0x27253d,.9),[0,.25,0],[w+.16,.5,d+.16]);
  // lit window grids on the side facing the play space
  const side=z<0?1:-1;
  const winColors=[0x182b47,0x35304e,0x184250,0x4c263f,0x283b52];
  for(let row=0;row<Math.min(5,Math.floor(h/1.5));row++) for(let col=0;col<Math.floor(w/1.15);col++){
    const wm=mat(winColors[(row*3+col*7)%winColors.length],.27,.15,{emissive:winColors[(row+col*2)%winColors.length],emissiveIntensity:.32});
    const wx=-w/2+.5+col*1.08, wy=1+row*1.3;
    if(wy<h-.3) addBox(g,wm,[wx,wy,side*(d/2+.012)],[.48,.65,.035],false);
  }
  if(sign){
    neonSign(g,sign,color,[0,1.35,side*(d/2+.08)],[Math.min(w-0.7,3),.78,.05]);
    const glow=new THREE.PointLight(color==='#ff72b1'?0xff378e:0x28cfff,7,9,2);glow.position.set(0,2,side*(d/2+1));g.add(glow);
  }
  return g;
}
building(-11,-15,8,5,11,'포차','#ff72b1');building(-2,-17,7,5,14,'SEOUL','#56dfff');building(8,-15,8,5,10,'CAFE 24','#ff72b1');
building(-12,14,7,5,12,'분식','#56dfff');building(-3,16,8,5,15,'NIGHT','#ff72b1');building(7,14,9,5,11,'노래방','#ff72b1');
building(-18,-5,5,8,9,'SHOP','#56dfff');building(18,-4,5,8,13,'편의점','#ff72b1');

// Plaza blocks and tactile street markings.
const plaza=new THREE.Group();scene.add(plaza);
addBox(plaza,mat(0x202338,.91),[0,-.045,0],[25,.09,29],false);
for(let x=-12;x<=12;x+=6){
  const line=addBox(plaza,mat(0x38394a,.86),[x,.009,0],[.09,.018,27],false);
}
for(let z=-13;z<=13;z+=6){addBox(plaza,mat(0x38394a,.86),[0,.01,z],[23,.02,.08],false);}
// Central pedestrian crossing stripes
for(let i=-4;i<=4;i++)addBox(plaza,mat(0xc5c9d2,.85),[i*.72,.024,-10],[.38,.025,2.1],false);
for(let i=-4;i<=4;i++)addBox(plaza,mat(0xc5c9d2,.85),[i*.72,.024,10],[.38,.025,2.1],false);
// lane separators
for(const z of [-5,5]) for(let x=-11;x<=11;x+=2.1)addBox(plaza,mat(0xaaa8a1,.9),[x,.022,z],[.9,.018,.065],false);
// Sidewalk boundary/curb
for(const z of [-13.9,13.9])addBox(plaza,mats.curb,[0,.06,z],[26,.2,.3]);
for(const x of [-12.4,12.4])addBox(plaza,mats.curb,[x,.06,0],[.3,.2,28]);

// Street lamps
const lamps=[];
function streetlamp(x,z){
  const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);
  const pole=addCylinder(g,mat(0x31354a,.35,.55),[0,2,0],.07,.1,4,8);
  addBox(g,mat(0x31354a,.35,.55),[.43,3.8,0],[.9,.08,.08]);
  addSphere(g,mat(0xffdba0,.3,.1,{emissive:0xffa948,emissiveIntensity:2}),[.82,3.7,0],[.18,.12,.16]);
  const light=new THREE.PointLight(0xffc97d,10,9,2);light.position.set(.82,3.55,0);g.add(light);lamps.push(light);
}
[[-10,-10],[10,-10],[-10,10],[10,10],[-10,0],[10,0]].forEach(p=>streetlamp(...p));

// Kiosks and street details
function kiosk(x,z){
 const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);
 addBox(g,mat(0x25283e),[0,.75,0],[2.5,1.5,1.8]);
 addBox(g,mat(0x26263b),[0,1.55,0],[2.8,.18,2.05]);
 addBox(g,mat(0x64dff1,.25,.1,{emissive:0x177786,emissiveIntensity:.8}),[0,1.05,.92],[1.9,.55,.035],false);
 neonSign(g,'호떡','#ff87a6',[0,1.05,.95],[1.15,.42,.02]);
 for(let i=-1;i<=1;i++)addBox(g,mat(0x171929),[i*.64,.22,1],[.08,.44,.08]);
}
kiosk(-7,-3);kiosk(7,3);

function tree(x,z){
 const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);
 addCylinder(g,mat(0x47372f),[0,.8,0],.16,.22,1.6,8);
 const green=mat(0x193b43,.9,{emissive:0x071216,emissiveIntensity:.08});
 for(const [y,s] of [[1.75,1.05],[2.35,.8],[2.85,.56]])addSphere(g,green,[0,y,0],[s,.72*s,s]);
 const planter=addBox(g,mat(0x343448),[0,.14,0],[1.2,.28,1.2]);
}
[[-11,-7],[-11,7],[11,-7],[11,7],[-7,12],[7,-12]].forEach(p=>tree(...p));

// Decorative neon floating motes
const moteGeo=new THREE.BufferGeometry();const moteN=120;const motePos=new Float32Array(moteN*3);
for(let i=0;i<moteN;i++){motePos[i*3]=(Math.random()-.5)*34;motePos[i*3+1]=Math.random()*5+.2;motePos[i*3+2]=(Math.random()-.5)*36;}
moteGeo.setAttribute('position',new THREE.BufferAttribute(motePos,3));
const motes=new THREE.Points(moteGeo,new THREE.PointsMaterial({color:0x73cfff,size:.045,transparent:true,opacity:.65,depthWrite:false}));scene.add(motes);

// Character builder: detailed, readable low-poly adult characters.
const characters=[];
function capsuleBetween(parent,a,b,r1,r2,material){
 const va=new THREE.Vector3(...a), vb=new THREE.Vector3(...b), d=new THREE.Vector3().subVectors(vb,va);
 const mesh=new THREE.Mesh(new THREE.CylinderGeometry(r2,r1,d.length(),9),material);
 mesh.position.copy(va).add(vb).multiplyScalar(.5);mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),d.normalize());mesh.castShadow=true;parent.add(mesh);return mesh;
}
function createOfficer(){
 const root=new THREE.Group();scene.add(root);root.position.set(0,0,2);
 const body=new THREE.Group();root.add(body);body.position.y=0;
 const uniform=mat(0x203b68,.46,.1), pants=mat(0x101c36,.52,.06), shirt=mat(0xd9e4f2,.5), skin=mat(0xe9b99b,.67), hair=mat(0x24172a,.34), shoe=mat(0x101018,.27,.12), gold=mat(0xe8c16c,.3,.48);
 // legs / tailored trousers
 const legs=[];
 for(const s of [-1,1]){
   const thigh=addBox(body,pants,[s*.18,.55,0],[.22,.72,.28]);
   const shin=addBox(body,pants,[s*.18,.2,.025],[.18,.38,.22]);
   const foot=addBox(body,shoe,[s*.18,.075,.15],[.21,.12,.34]);
   addBox(body,mat(0x252536,.28,.1),[s*.18,.035,.15],[.22,.05,.35]);
   legs.push({thigh,shin,foot,side:s});
 }
 // jacket torso and skirt-like uniform hem
 const torso=addBox(body,uniform,[0,1.12,0],[.62,.75,.34]);
 const lower=addBox(body,uniform,[0,.79,0],[.65,.18,.38]);
 // white shirt insert, collar lapels
 addBox(body,shirt,[0,1.34,.182],[.22,.38,.025]);
 const lapelL=addBox(body,shirt,[-.12,1.46,.195],[.15,.16,.03]);lapelL.rotation.z=-.42;
 const lapelR=addBox(body,shirt,[.12,1.46,.195],[.15,.16,.03]);lapelR.rotation.z=.42;
 for(let y=1.48;y>1.02;y-=.12)addSphere(body,gold,[0,y,.19],[.022,.022,.018]);
 // belt / badge / shoulder epaulettes
 addBox(body,mat(0x101a30,.42,.2),[0,.88,0],[.65,.1,.39]);
 addBox(body,gold,[.12,.89,.205],[.09,.08,.025]);
 addBox(body,gold,[-.2,1.42,.19],[.1,.07,.035]);
 addBox(body,uniform,[-.29,1.43,0],[.12,.1,.38]);addBox(body,uniform,[.29,1.43,0],[.12,.1,.38]);
 // arms with sleeves / hands
 const armL=new THREE.Group(),armR=new THREE.Group();
 for(const [arm,s] of [[armL,-1],[armR,1]]){
