// Sound is generated locally by Web Audio; no external assets.
function sound(type='hit'){
 if(state.muted)return;
 try{
  const C=window.AudioContext||window.webkitAudioContext;if(!C)return;
  if(!state.audio)state.audio=new C();const ctx=state.audio;if(ctx.state==='suspended')ctx.resume();
  const now=ctx.currentTime,osc=ctx.createOscillator(),gain=ctx.createGain();
  osc.connect(gain);gain.connect(ctx.destination);
  const tones={hit:[360,180,.14,'sawtooth'],catch:[620,960,.28,'triangle'],miss:[190,80,.34,'sawtooth'],slash:[280,90,.16,'triangle'],start:[440,740,.2,'sine']};
  const [a,b,d,w]=tones[type]||tones.hit;osc.type=w;osc.frequency.setValueAtTime(a,now);osc.frequency.exponentialRampToValueAtTime(b,now+d);
  gain.gain.setValueAtTime(.0001,now);gain.gain.exponentialRampToValueAtTime(.065,now+.012);gain.gain.exponentialRampToValueAtTime(.0001,now+d);
  osc.start(now);osc.stop(now+d+.02);
 }catch(_){ }
}

function spawnThief(){
 if(state.enemies.length>=4)return;
 const thief=createThief();
 const angle=Math.random()*Math.PI*2,r=9.7+Math.random()*2.2;
 thief.root.position.set(Math.cos(angle)*r,0,Math.sin(angle)*r);
 thief.root.rotation.y=Math.atan2(-thief.root.position.x,-thief.root.position.z);
 thief.escape=11.5+Math.random()*4;state.enemies.push(thief);
 if(state.mode==='playing'&&state.enemies.length===1)toast('ŞÜPHELİ GÖRÜLDÜ <small>• TAKİPTE</small>','pink');
}
function catchThief(e){
 e.alive=false;const index=state.enemies.indexOf(e);if(index>=0)state.enemies.splice(index,1);
 scene.remove(e.root);const ci=characters.indexOf(e);if(ci>=0)characters.splice(ci,1);
 state.combo++;state.bestCombo=Math.max(state.bestCombo,state.combo);state.caught++;
 const base=100+Math.floor(Math.max(0,state.time)*.8),points=base*Math.min(state.combo,5);state.score+=points;
 state.time=Math.min(100,state.time+2.2);state.slashCd=Math.max(state.slashCd,.12);
 sound('catch');state.shake=.13;
 toast(`+${points} <small>PUAN • ×${state.combo} KOMBO</small>`,'');
 if(state.combo===3||state.combo===5||state.combo===10)showBanner(`${state.combo}× KOMBO!`);
}
function missThief(e){
 const index=state.enemies.indexOf(e);if(index>=0)state.enemies.splice(index,1);
 scene.remove(e.root);const ci=characters.indexOf(e);if(ci>=0)characters.splice(ci,1);
 state.lives--;state.combo=0;state.time=Math.max(0,state.time-5);sound('miss');state.shake=.2;
 const h=document.querySelectorAll('.heart')[state.lives];if(h){h.classList.add('lost');setTimeout(()=>h.classList.remove('lost'),600);}
 toast('HIRSIZ KAÇTI <small>−1 KALP • −5 SN</small>','pink');
 if(state.lives<=0)endGame(false);
}
function strike(){
 if(state.mode!=='playing'||state.slashCd>0)return;
 state.slashCd=.72;player.armR.rotation.x=-1.1;setTimeout(()=>{player.armR.rotation.x=0;},180);
 sound('slash');let target=null,dist=2.65;
 for(const e of state.enemies){const d=player.root.position.distanceTo(e.root.position);if(d<dist){dist=d;target=e;}}
 if(target){catchThief(target);}
 else{player.body.rotation.x=-.06;setTimeout(()=>{player.body.rotation.x=0;},130);}
}

