// Virtual joystick starts where the player touches, capped to its base radius.
const stick=$('stick'),knob=$('.stick-knob');let joyPointer=null,joyOrigin={x:0,y:0};
canvas.addEventListener('pointerdown',e=>{
 if(state.mode!=='playing'||!matchMedia('(pointer:coarse)').matches||e.clientX>innerWidth*.58)return;
 joyPointer=e.pointerId;canvas.setPointerCapture(e.pointerId);joyOrigin={x:e.clientX,y:e.clientY};
 stick.style.left=`${e.clientX}px`;stick.style.top=`${e.clientY}px`;stick.classList.add('on');moveJoy(e);
});
function moveJoy(e){if(joyPointer!==e.pointerId)return;const dx=e.clientX-joyOrigin.x,dy=e.clientY-joyOrigin.y,r=45,len=Math.hypot(dx,dy),k=len>r?r/len:1;const x=dx*k,y=dy*k;knob.style.left=`calc(50% + ${x}px)`;knob.style.top=`calc(50% + ${y}px)`;state.joy.x=x/r;state.joy.y=-y/r;}
canvas.addEventListener('pointermove',moveJoy);
function endJoy(e){if(joyPointer!==e.pointerId)return;joyPointer=null;state.joy.x=state.joy.y=0;stick.classList.remove('on');knob.style.left='50%';knob.style.top='50%';}
canvas.addEventListener('pointerup',endJoy);canvas.addEventListener('pointercancel',endJoy);

// Minimap draws the live plaza and entity positions.
const map=$('minimap'),mapCtx=map.getContext('2d');
function drawMap(){
 const c=mapCtx,w=map.width,h=map.height;c.clearRect(0,0,w,h);c.fillStyle='#090d1d';c.fillRect(0,0,w,h);
 c.strokeStyle='rgba(100,145,200,.16)';c.lineWidth=1;
 for(let x=0;x<w;x+=30){c.beginPath();c.moveTo(x,0);c.lineTo(x,h);c.stroke();}for(let y=0;y<h;y+=30){c.beginPath();c.moveTo(0,y);c.lineTo(w,y);c.stroke();}
 c.fillStyle='rgba(100,116,150,.25)';c.fillRect(20,12,w-40,h-24);
 const px= x=>w/2+x*7.2,py=z=>h/2+z*6.8;
 c.strokeStyle='rgba(150,170,210,.25)';c.lineWidth=2;c.strokeRect(px(-12),py(-14),24*7.2,28*6.8);
 c.fillStyle='rgba(255,255,255,.13)';for(let i=-4;i<=4;i++){c.fillRect(px(i*.72)-1,py(-10)-6,3,12);c.fillRect(px(i*.72)-1,py(10)-6,3,12);}
 for(const e of state.enemies){c.beginPath();c.fillStyle='#ff4d9d';c.shadowColor='#ff4d9d';c.shadowBlur=9;c.arc(px(e.root.position.x),py(e.root.position.z),4.4,0,Math.PI*2);c.fill();}
 c.shadowBlur=0;c.beginPath();c.fillStyle='#4fe6ff';c.shadowColor='#4fe6ff';c.shadowBlur=10;c.arc(px(player.root.position.x),py(player.root.position.z),4.8,0,Math.PI*2);c.fill();c.shadowBlur=0;
}

// Simple hit sparks: short-lived neon rings on successful catches.
const effects=[];
function makeBurst(position){
 const group=new THREE.Group();group.position.copy(position);group.position.y=.12;scene.add(group);
 const ring=new THREE.Mesh(new THREE.RingGeometry(.18,.28,24),new THREE.MeshBasicMaterial({color:0x55eaff,transparent:true,opacity:.9,side:THREE.DoubleSide}));ring.rotation.x=-Math.PI/2;group.add(ring);
 for(let i=0;i<8;i++){
  const a=i/8*Math.PI*2;const dot=new THREE.Mesh(new THREE.SphereGeometry(.055,8,6),new THREE.MeshBasicMaterial({color:i%2?0xff65a7:0xffe487}));
  dot.position.set(Math.cos(a)*.28,.04,Math.sin(a)*.28);group.add(dot);
 }
 effects.push({group,age:0});
}
const oldCatch=catchThief;
// Wrap catch for an impact burst while preserving scoring/audio logic.
catchThief=function(e){makeBurst(e.root.position.clone());oldCatch(e);};

let prev=performance.now();
function animate(now){
 requestAnimationFrame(animate);
 const dt=Math.min(.04,(now-prev)/1000||0);prev=now;state.elapsed+=dt;
 pinkLight.intensity=25+Math.sin(state.elapsed*1.8)*4;cyanLight.intensity=22+Math.sin(state.elapsed*1.35+1)*4;
 for(let i=0;i<moteN;i++)motePos[i*3+1]+=(Math.sin(state.elapsed*.45+i)*.0008);
 moteGeo.attributes.position.needsUpdate=true;
 if(state.mode==='playing'){
  state.time=Math.max(0,state.time-dt);state.slashCd=Math.max(0,state.slashCd-dt);
  if(state.time<=0){state.time=0;updateHud();endGame(true);}
  const keyX=(state.keys.KeyD||state.keys.ArrowRight?1:0)-(state.keys.KeyA||state.keys.ArrowLeft?1:0);
  const keyY=(state.keys.KeyS||state.keys.ArrowDown?1:0)-(state.keys.KeyW||state.keys.ArrowUp?1:0);
  let mx=keyX+state.joy.x,mz=keyY-state.joy.y;
  const ml=Math.hypot(mx,mz);if(ml>1){mx/=ml;mz/=ml;}
  const moving=ml>.08;
  if(moving){
   const sp=5.1;player.root.position.x=THREE.MathUtils.clamp(player.root.position.x+mx*sp*dt,-11.2,11.2);
   player.root.position.z=THREE.MathUtils.clamp(player.root.position.z+mz*sp*dt,-12.1,12.1);
   player.root.rotation.y=Math.atan2(mx,mz);player.walk+=dt*11;
   player.body.position.y=Math.abs(Math.sin(player.walk))*.035;
   player.legs.forEach((l,i)=>{const a=Math.sin(player.walk+i*Math.PI)*.52;l.thigh.rotation.x=a;l.shin.rotation.x=Math.max(0,-a)*.7;l.foot.rotation.x=a*.25;});
   player.armL.rotation.x=-Math.sin(player.walk)*.36;player.armR.rotation.x=Math.sin(player.walk)*.36;
  }else{
   player.body.position.y=Math.sin(state.elapsed*2)*.012;
   player.legs.forEach(l=>{l.thigh.rotation.x*=.82;l.shin.rotation.x*=.82;l.foot.rotation.x*=.82;});
   player.armL.rotation.x*=.86;player.armR.rotation.x*=.86;
  }
  state.spawnIn-=dt;
  if(state.spawnIn<=0){spawnThief();state.spawnIn=Math.max(2.6,4.6-state.caught*.12)+Math.random()*1.1;}
  for(const e of [...state.enemies]){
   const pos=e.root.position,dx=pos.x,dz=pos.z,r=Math.hypot(dx,dz)||1;
   // The suspect flees toward the outer exits, with a little evasive sideways weave.
   const weave=Math.sin(state.elapsed*3+e.root.id)*.28;
   const vx=dx/r+(-dz/r)*weave,vz=dz/r+(dx/r)*weave,vl=Math.hypot(vx,vz)||1;
   pos.x+=vx/vl*e.speed*dt;pos.z+=vz/vl*e.speed*dt;
   e.root.rotation.y=Math.atan2(vx,vz);e.walk+=dt*9;
   e.body.position.y=Math.abs(Math.sin(e.walk))*.045;
   e.body.rotation.z=Math.sin(e.walk)*.04;
   e.armL.rotation.x=Math.sin(e.walk)*.55;e.armR.rotation.x=-Math.sin(e.walk)*.55;
   e.bag.rotation.z=Math.sin(e.walk*1.4)*.08;
   e.escape-=dt;
   if(Math.hypot(pos.x,pos.z)>13.1||e.escape<=0)missThief(e);
  }
  // Camera follows while keeping a little look-ahead in movement direction.
  const p=player.root.position;
  const target=new THREE.Vector3(p.x*.62-.4,1.0,p.z*.62-1.4);
  const desired=new THREE.Vector3(p.x+10.5,13.2,p.z+15.2);
  camera.position.lerp(desired,1-Math.exp(-dt*3.2));
  if(state.shake>0){state.shake=Math.max(0,state.shake-dt);camera.position.x+=(Math.random()-.5)*state.shake*1.5;camera.position.y+=(Math.random()-.5)*state.shake;}
  camera.lookAt(target);
  updateHud();drawMap();
 }else{
  // Slow cinematic orbit, showing the Seoul street while the menu is open.
  const target=new THREE.Vector3(-2,.7,0);
  const a=state.elapsed*.035;
  const desired=new THREE.Vector3(11+Math.sin(a)*1.5,11,21+Math.cos(a)*1.4);
  camera.position.lerp(desired,1-Math.exp(-dt*1.25));camera.lookAt(target);
  player.root.position.set(-.6+Math.sin(state.elapsed*.5)*.24,0,1.4);
  player.root.rotation.y=-.3+Math.sin(state.elapsed*.4)*.12;
  player.body.position.y=Math.sin(state.elapsed*1.7)*.018;
  player.head.rotation.y=Math.sin(state.elapsed*.7)*.045;
  if(state.mode==='menu')drawMap();
 }
 for(let i=effects.length-1;i>=0;i--){const fx=effects[i];fx.age+=dt;const t=fx.age/.48;fx.group.scale.setScalar(1+t*3);fx.group.children.forEach(o=>{if(o.material)o.material.opacity=Math.max(0,1-t);});if(t>=1){scene.remove(fx.group);effects.splice(i,1);}}
 renderer.render(scene,camera);
}
